<template><div style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:16px"><a-card style="width:min(420px,100%)"><h2>首次登录请修改密码</h2><a-form :model="form" @submit="submit"><a-form-item label="原密码"><a-input-password v-model="form.currentPassword"/></a-form-item><a-form-item label="新密码"><a-input-password v-model="form.newPassword"/></a-form-item><a-form-item label="确认新密码"><a-input-password v-model="form.confirm"/></a-form-item><a-button type="primary" html-type="submit" long :loading="loading">保存并继续</a-button></a-form></a-card></div></template>
<script setup>import {reactive,ref} from 'vue';import {Message} from '@arco-design/web-vue';import {useRouter} from 'vue-router';import http from '../api/http';const router=useRouter();const loading=ref(false);const form=reactive({currentPassword:'',newPassword:'',confirm:''});const submit=async()=>{if(form.newPassword!==form.confirm){Message.error({content:'两次新密码不一致',duration:5000});return;}loading.value=true;try{await http.post('/auth/change-password',{currentPassword:form.currentPassword,newPassword:form.newPassword});window.__user={...window.__user,mustChangePassword:false};router.push('/')}catch(e){Message.error({content:e.message,duration:5000})}finally{loading.value=false}};</script>
